# Чтение (21-24): переплата ЗП (Дт 3350) на 30.06.2025 — по сотруднику: начислено/выплачено 2025, сальдо на 30.06.2025 и сейчас, чем выплачено
N0 = datetime.datetime(2025, 1, 1, 6); D = datetime.datetime(2025, 7, 1, 6)
rows = q("""ВЫБРАТЬ О.Организация КАК Орг, О.Субконто1 КАК С, СУММА(О.СуммаОстатокДт - О.СуммаОстатокКт) КАК Ост
 ИЗ РегистрБухгалтерии.{REG}.Остатки(&Д, Счет.Код = "3350", , ) КАК О СГРУППИРОВАТЬ ПО О.Организация, О.Субконто1
 ИМЕЮЩИЕ СУММА(О.СуммаОстатокДт - О.СуммаОстатокКт) > 1000 УПОРЯДОЧИТЬ ПО Ост УБЫВ""", Д=D)
now = {(s(r["Орг"]), s(r["С"])): float(r["Ост"]) for r in q("""ВЫБРАТЬ О.Организация КАК Орг, О.Субконто1 КАК С, СУММА(О.СуммаОстатокДт - О.СуммаОстатокКт) КАК Ост
 ИЗ РегистрБухгалтерии.{REG}.Остатки(, Счет.Код = "3350", , ) КАК О СГРУППИРОВАТЬ ПО О.Организация, О.Субконто1""")}
print(f"{'сотрудник':32} {'сальдо 30.06':>12} {'сейчас':>12} {'начисл.25':>12} {'выпл.25':>12}  выплачено документами")
for r in rows:
    emp = r["С"]
    t = q("""ВЫБРАТЬ СУММА(О.СуммаОборотКт) КАК Кт, СУММА(О.СуммаОборотДт) КАК Дт ИЗ РегистрБухгалтерии.{REG}.Обороты(&Н, &Д, , Счет.Код = "3350", , Субконто1 = &Е, , ) КАК О""", Н=N0, Д=D, Е=emp)[0]
    by = q("""ВЫБРАТЬ ТИПЗНАЧЕНИЯ(П.Регистратор) КАК Т, П.СчетКт.Код КАК Кт, СУММА(П.Сумма) КАК С ИЗ РегистрБухгалтерии.{REG} КАК П
      ГДЕ П.Период МЕЖДУ &Н И &Д И П.СчетДт.Код = "3350" И П.СубконтоДт1 = &Е СГРУППИРОВАТЬ ПО ТИПЗНАЧЕНИЯ(П.Регистратор), П.СчетКт.Код""", Н=N0, Д=D, Е=emp)
    k = (s(r["Орг"]), s(emp))
    print(f"{s(emp)[:32]:32} {float(r['Ост']):12,.0f} {now.get(k, 0):12,.0f} {float(t['Кт'] or 0):12,.0f} {float(t['Дт'] or 0):12,.0f}  " +
          "; ".join(f"{s(b['Т'])[:22]}/{s(b['Кт'])} {float(b['С']):,.0f}" for b in by))
